export const phoneticBank = {
  initials: soundInitialData.map(
    ([id, a, b, kind, place, articulation, near]) => ({
      id,
      kind,
      place,
      articulation,
      near: near.split(" "),
      examples: [a, b].map((s) => {
        const [hanzi, pinyin] = s.split("|");
        return { hanzi, pinyin };
      }),
    }),
  ),
  finals: soundFinalData.map(([id, a, b, kind, articulation, near]) => ({
    id,
    kind,
    articulation,
    near: near.replace("uen-placeholder", "en").split(" "),
    examples: [a, b].map((s) => {
      const [hanzi, pinyin] = s.split("|");
      return { hanzi, pinyin };
    }),
  })),
};
